def is_palindrome(s):
    return s == s[::-1]

def is_yalalovichik(s):
    substring_set = set()
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substring = s[i:j]
            for k in range(len(substring) // 2):
                if substring[k] != substring[-1 - k]:
                    break
            else:
                substring_set.add(substring)
    return len(substring_set) == len(set(substring_set))

def count_yalalovichik_substrings(n, s):
    substrings = set()
    for i in range(n):
        substring = s[:i+1]
        if is_palindrome(substring) or is_yalalovichik(substring):
            substrings.add(substring)
    return len(substrings)

