        length, beauty = query
        permutations = []
        team = [i for i in range(1, length + 1)]
        for roll in range(1 << (length // 2)):
            subset = list(combinations(team, length // 2))
            if (roll % 2 == 0):
                temp = roll // 2 + roll // 2 * 2
            else:
                temp = (roll // 2 + 1) * 2
            start, end = (temp * 2) - length + 1, length - temp

            new_subset = set()
            for i in range(start, end + 1):
                for comparison in subset:
                    if len(new_subset) <= i:
                        new_subset.add(comparison)
                    elif len(new_subset) > i:
                        new_subset = new_subset - set(new_subset).difference(comparison)
                        if len(new_subset) <= i:
                            new_subset = new_subset.union(comparison)

            team = list(new_subset)
            permutations.append(tuple(team))
