def is_good_graph(G: List[List[int]]) -> bool:
    # Check if a graph is a good graph with vertex 1 and vertex N not connected.
    return len(set(G[i][0:2] for i in range(len(G))) - {(1, 1), (N, N)}) > 1

def can_move(G: List[List[int]], u: int, v: int) -> bool:
    # Check if it's possible to add an edge between u and v.
    return all((i, j) not in G for i in (u, v) for j in (1, N))

def determine_winner(G: List[List[int]], T: int, case_id: int) -> str:
    # Determine the winner for a given Test Case.
    if len(G) == (T + 1) ** 2 // (T + 1) - 1:
        return 'First'  # Taro the first wins if the number of edges is large enough.
    for i in range(len(G)):
        if not can_move(G, i + 1, i + 2) and not can_move(G, i + 2, i + 1):
            # Taro can't make a move, so Jiro wins.
            return 'Second'
    # If neither player can make a move, the game is stuck and loses to Jiro.
    return 'Second'

def solve(test_cases: List[List[int]]) -> List[str]:
