            while (frontier[0] - frontier[2]) * (frontier[1] - frontier[3]) < 0:
                odd_table[frontier[0]] = *odd_table[frontier[1]], max_odd + 2, 0
                even_table[frontier[1]] = *even_table[frontier[0]], max_odd, 0
                if frontier[2] - frontier[0] > farthest:
                    farthest = frontier[2] - frontier[0]
                    max_odd = even_table[frontier[0]][2] if even_table[frontier[0]] else odd_table[frontier[0]][2]
