from heapq import heappush, heappop

def can_be_made_G(N, edges):
    # Build adjacency list
    graph = [[] for _ in range(N)]
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    # Function to check if graph edges can be removed
    def can_be_removed(u, v):
        seen = [0] * N
        seen[u] = 1
        queue = [u]
        while queue:
            cur = queue.pop()
            for next_v in graph[cur]:
                if seen[next_v] == 0:
                    seen[next_v] = 1
                    heappush(queue, next_v)
        return seen[v] == 1

    # Find if graph is good
    edges_taken = set()
    for u in range(N):
        for v in graph[u]:
            if (u, v) in edges_taken or (v, u) in edges_taken:
                continue
            if not can_be_removed(u, v):
                return False
            heappush(edges_taken, (max(u, v) + 1, min(u, v)))
    return True

def find_winner(num_cases):
    # Edge cases
    if num_cases < 2:
        return 'First'
    elif num_cases != 2:
        # Check if graph can be made good after removal
        if num_cases == 1:
            return can_be_made_G(2, [[1, 2]])
        else:  # More than 1 test cases
            return 'First'

if __name__ == "__main__":
