from collections import defaultdict, deque
from functools import lru_cache

# Define Fibonacci sequence for memoization
MOD = 998244353
def fib(n):
    if n == 0 or n == 1:
        return 1
    previous, current = 1, 1
    for _ in range(2, n + 1):
        previous, current = current, (previous + current) % MOD
    return current

# Input function
def input():
    import sys
    return sys.stdin.readline().strip()

def main():
    n = int(input())

    # Create adjacency list from the input edges
    trees = defaultdict(dict)
    for u, v in (((int(i.split()[0]), int(i.split()[1])) for i in input().split("\n"))):
        trees[u-1][v-1] = 1
        trees[v-1][u-1] = 1

    # Function to traverse the tree and calculate unique matchings for each component
    @lru_cache(maxsize=None)
    def unique_matching(node, visited, cut):
        visited[node] = 1
        path = 0
        for neigh in trees[node]:
            if neigh not in visited or not visited[neigh] or neigh in cut:
                continue
            path += 1 + unique_matching(neigh, visited, cut)
        if node in cut:
            path = 0 if path % 2 == 1 else 1  # Ensure we get unique matching after cutting node
        return path

    max_matchings = 0
    for node in trees:
        if node not in cut:
            max_matchings += fib(n-1)  # Add all possible matchings for each node
    max_matchings %= MOD

    print(max_matchings)

if __name__ == "__main__":
    main()
