from bisect import bisect
from collections import defaultdict

def ceil(value, step):
    return (value + step - 1) // step

class SegTree:
    def __init__(self, values):
        self.n = ceil(len(values) ** 0.5, 1)
        self.bit = [[defaultdict(list) for _ in range(self.n)] for _ in range(self.n)]
        self.inverse = [0] * (2 * self.n)
        self._values = values
        self._set_all()

    def _set_all(self):
        for index, value in enumerate(self._values):
            base = index
            while base < len(self.inverse):
                self.inverse[base] = value
                base += min(base + 1, self.n - 1)

    def update(self, pos, value):
        self._set_all()
        while pos < len(self.inverse):
            cur = pos + 2 * self.n
            for key, dict_ in self.inverse:
                if value in [self.inverse[top] for top in dict_[key]]:
                    for pos, current in dict_[key].items():
                        self.bit[key][pos] = current
                    dict_[value].append(cur)
            pos = cur

    def query(self, l, r, key=None):
        ans = []
        self._set_all()
        l, r = l - 1, r
        if key is not None:
            for ind, pos in self.inverse[key].items():
                dict_ = self.bit[ind]
                start = bisect(self.inverse[ind][self.inverse[ind][pos]], l)
                end = bisect(self.inverse[ind][self.inverse[ind][pos]], r)
                if start == len(self.inverse[ind][self.inverse[ind][pos]]):
                    start -= 1
                if end == len(self.inverse[ind][self.inverse[ind][pos]]):
                    end -= 1
                ans += [self.inverse[ind][self.inverse[ind][pos]][pos]] * (end - start + 1)
        return ans


