def reconstruct_palette(operation_records, operation_counts):
    palette = ["."] * 4  # Initially, all cells are empty
    mix_stack = deque()
    cell_indices = set()

    # Add the initial counts of each color to mixed operations
    for i, operation_count in enumerate(operation_counts):
        if operation_count > 1:
            color = parse_operation(operation_records[i], cell_indices)
            mix_stack.append(color)
        else:
            color = parse_operation(operation_records[i], cell_indices)
            # If it's not a mix, add it to the stack directly
            mix_stack.append(color)

    # Process remaining mixes in reverse order
    while mix_stack:
        color = mix_stack.pop()
        cell_indices.discard(mix_stack[-1])
        if color in ('Y', 'R', 'B'):
            cell_indices |= set(mix_stack)
            break  # All operations are accounted for

    # Attempt to balance the palette
    for color in ('Y', 'R', 'B'):
        if color not in cell_indices:
            cell_indices |= set(mix_stack)
            break

    if len(cell_indices) != 4:
        return "NO"
    return "YES\n" + ''.join(palette[cell_indices[i]] for i in range(4))

