                x_disjunction = max(x_disjunction_i, x_disjunction)
                neg_disjunction = max(neg_disjunction_i, neg_disjunction)
            else:
                x_disjunction_i = max(x_disjunction, -num_disjunction - i)
                neg_disjunction_i = max(neg_disjunction, -num_disjunction + i)
                x_disjunction = max(x_disjunction_i, x_disjunction)
                neg_disjunction = max(neg_disjunction_i, neg_disjunction)
        x_disjunction += neg_disjunction
        if x_disjunction in x_disjunctions:
            x_disjunctions[x_disjunction].append(i)
        else:
            x_disjunctions[x_disjunction] = [i]
        if neg_disjunction in neg_disjunctions:
            neg_disjunctions[neg_disjunction].append(i)
        else:
            neg_disjunctions[neg_disjunction] = [i]
    return x_disjunctions, neg_disjunctions

def are_similar(x_disjunctions, neg_disjunctions, f_values, g_values):
    for key, value in x_disjunctions.items():
        if len(value) != len(f_values) or len(value) != len(g_values):
            return False
        if len(set(neg_disjunctions[key]) & set(f_values)) or len(set(neg_disjunctions[key]) & set(g_values)):
            return False
    return True

def solve_2sat(f1, f2, g1, g2):
    variables = 2 * len(f1)
    f1_disjunctions, f1_neg_disjunctions = parse_formula(variables, f1)
    f2_disjunctions, f2_neg_disjunctions = parse_formula(variables, f2)
    g1_disjunctions, g1_neg_disjunctions = parse_formula(variables, g1)
    g2_disjunctions, g2_neg_disjunctions = parse_formula(variables, g2)

    x_disjunctions_f1_f2 = [(x_f2 - x_f1) for x_f1, x_f2 in [(f1[d1], f2[d2]) for d1 in f1_disjunctions if d2 in f2_disjunctions] if x_f2 - x_f1 % 2 == 1]  # adjusting for possible odd values of disjunctions
    neg_disjunctions_f1_f2 = [
        (x_neg2 - x_neg1) * 2 
        for x_neg1, x_neg2 in [(g1[neg1], g2[neg2]) for neg1, neg2 in [(g1[d1*(-1)], g2[d2*(-1)]) for d1 in g1_neg_disjunctions if d2 in g2_neg_disjunctions] if neg1 - neg2 % 2 == 1]
        if x_neg2 - x_neg1 % 4 == 1  # ensuring disagreement on negative disjunctions
    ]

    x_disjunctions_g1_g2 = [(x_m2 - x_m1)*2 for x_m1, x_m2 in [(g1[d1], g2[d2]) for d1 in g1_disjunctions if d2 in g2_disjunctions] if x_m2 - x_m1 % 4 == 1  # ensuring disagreement on positive disjunctions]
    neg_disjunctions_g1_g2 = [
        ((x_g1 * 2) - (x_g2 * 2 - x_g22 + x_g21)) 
        for x_g1, x_g2 in [(g1[d1], g2[d1]) for d1 in g1_disjunctions if d1 in g2_disjunctions]
        for x_g11, x_g22, x_g12 in [(g1[d1 + d2 * 2], g2[d3 + d2 * 2], g1[d3]) for d3 in g2_disjunctions for d2 in [d1, d1 + d2]] 
        if (x_g12 - x_g22 + x_g11) % 2 == 0  # ensuring agreement on negation disjunctions
    ]

    if are_similar(x_disjunctions_f1_f2, neg_disjunctions_g1_g2, f2, g1) and are_similar(2 * x_disjunctions_f1_f2, neg_disjunctions_f1_f2, f1, g2):
        return "SIMILAR"
    else:
        return " ".join(map(str, x_disjunctions_g1_g2))
