            perm[j - 1:i - 1] = rank * [i] + (len(dp_new) - j) * [-1]
            dp_new = update_dp(i - 1, perm[:i], k, dp_new)

    if dp_new:
        return "YES\n" + "\n".join(map(str, perm))
    else:
