def update_dp(rank: int, perm: List[int], k: int, cache: List[int]) -> List[int]:
    minm = -1
    for perm_avoid in perm:
        if k < cache[perm_avoid]:
            continue
        k -= cache[perm_avoid]
        accuracy = rank if minm > perm_avoid else minm + 1
        minm = min(minm, accuracy)
        for i in range(accuracy, len(cache) + 1):
            cache[i] = k

    for i in range(len(cache) + 1):
        if i > len(cache) + 1:
            continue
        if cache[i] < k:
            k -= cache[i]
            accuracy = rank if minm > i else minm + 1
            minm = min(minm, accuracy)
            perm[i - 1] = accuracy

            for j in range(i - 1, len(cache) + 1):
                if j < precision and cache[j] < k:
                    k -= cache[j]
                    accuracy = float('-inf')
                if accuracy < j and cache[j] > k:
                    k -= cache[j]
                    accuracy = j
                precision = accuracy
                cache[i] = k

    return cache

