    for i, cost in enumerate(charges[:-1]):
        balance[i] = 0  # Start with a balance of 0 for the next cost
    balance[-1] = charges[-1]  # For the last day, keep the cost

    # Calculate the minimum cash spending
    for i in range(num_days):
        if charges[i] in [1000, 2000]:
            balance[i] -= cost
        else:
            three_days_balance = sum(balance[i - 2:i + 1])
            min_cash = floor((2000 - charges[i]) / 3)
            if three_days_balance - min_cash * 2 >= 0:
                balance[i] = three_days_balance - (charges[i] - min_cash * 3)
            elif three_days_balance - min_cash * 2 - charges[i] >= 0:
                new_balance = sum((balance[j - 2:j + 1]) for j in range(i + 1, num_days))
                min_cash = floor((3000 - charges[i]) / 3)
                if new_balance - min_cash * 2 >= 0:
                    balance[i] = new_balance - min_cash * 2
                elif new_balance - min_cash * 2 - charges[i] >= 0:
                    new_balance = sum((balance[j - 2:j + 1]) for j in range(i + 1, num_days))
                    min_cash = floor((4000 - charges[i]) / 3)
                    if new_balance - min_cash * 2 >= 0:
                        balance[i] = new_balance - min_cash * 2
                    else:
                        min_cash = floor((3000 - charges[i]) / 2)
                        balance[i] = new_balance - min_cash 
            else:
                totale = min(balance[i - 1] + (charges[i] - 1) // 3, charges[i] // 2)
                balance[i] = totale - (charges[i] - totale) // 3
        balance[i] = max(balance[i] - 1200, 0)  # Limit the balance with negative bonuses
    return min(balance[i] for i in range(num_days))
