    for sequence in sequences:
        sorted_sequence = sorted(sequence)
        character_sets[sorted_sequence].append(sequence)
    return list(character_sets.values())

def count_yns(s: str) -> int:
    if len(s) < 2:
        return 0
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    result = 1
    for count in char_count.values():
        fourth_power = count ** 2
        result *= (third_power := fourth_power + 1) % 9 * 2 + 1
    return result % 9

def solve(t: int) -> None:
