from collections import defaultdict, deque

def solve(n, m, tracks):
    graph = defaultdict(list)
    for x, y in tracks:
        graph[x].append(y)
        graph[y].append(x)

    def bfs(source, visited):
        queue = deque([(source, 1)])
        visits = [0]
        while queue:
            node, level = queue.popleft()
            visits[node] = level
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    queue.append((neighbor, level + 1))
                    visited[neighbor] = True
        return visits

    close = set()
    while close < n:
        visited = [False] * (n + 1)
        level = bfs(1, visited)
        cond = all(level[node] <= 4 for node in range(1, n + 1))
        if cond:
            closest = min((level[node], node) for node in range(1, n + 1))[1] + 1
            while True:
                node = closest
                if level[node] >= 4:
                    close.add(node)
                    closest = max(map(lambda x: visited[x] and x == node and visited[node] >= 1, graph[node]))
                else:
                    break
    return len(close), close

