def is_good_graph(graph, a, b):
    # Check if adding an edge between a and b makes the graph no longer good
    for i in range(len(graph)):
        if graph[i][0] == a or graph[i][1] == a or graph[i][0] == b or graph[i][1] == b:
            # Check all edges in the graph except the one between a and b
            all_edges_except_ab = [edge for edge in graph if edge != (a, b) and edge != (b, a) and edge[0] != edge[1]]
            for other_edge in all_edges_except_ab:
                if are_edges_cross(other_edge, (a, b)):
                    return False
    return True

def are_edges_cross(edge_a, edge_b):
    (x1, y1), (x2, y2) = edge_a
    (x3, y3), (x4, y4) = edge_b
    return (x1 < x3 < x4 <= x2) or (x1 < x2 < x4 <= x3) or (y1 < y3 < y4 <= y2) or (y1 < y2 < y4 <= y3)

