import sys
from bisect import bisect_left, bisect_right

class LeafletDatabase:
    def __init__(self, swear_word, leaflets):
        self.swear_word = swear_word
        self.leaflets = leaflets
        self.segment_counts = [{} for _ in range(len(swear_word))]

    def update_swear_word_segment(self, location, count):
        start, end = location, end - len(self.swear_word)
        for start_loc in range(max(location, start), location):
            for end_loc in range(location, min(location, end)):
                segment_key = self.swear_word[start_loc:end_loc]
                self.segment_counts[end_loc[max(0, start_loc):]].setdefault(segment_key, 0)
                self.segment_counts[end_loc[max(0, start_loc):]][segment_key] += count

    def query(self, l, r):
        best = -1
        best_count = 0
        for location in range(l - 1, r):
            if not location < len(self.leaflets)[0]:
                return -1, -1  # Leaflet doesn't exist in segment
            while location + len(self.swear_word) - 1 < len(self.leaflets[0]):
                if self.leaflets[location // len(swear_word)][location:(location + len(self.swear_word))] == self.swear_word:
                    self.update_swear_word_segment(location, 1)
                    break
                else:
                    self.update_swear_word_segment(location, -1)
                    location += len(swear_word)
            else:
                location = len(self.leaflets[0])
            for segment_key, count in self.segment_counts[location[(location - 1) % len(self.swear_word):]]:
                if segment_key in self.segment_counts and count > best_count:
                    best = segment_key
                    best_count = count

        return best, best_count

class QueryEngine:
    def __init__(self):
        self.leaflet_database = None

    def read_queries(self, lines):
        self.leaflet_database = LeafletDatabase(sys.stdin.readline().strip(), [])

        for line in lines:
            m, *qa = line.split()
            if m != len(qa):
                return None
            for leaflet in qa:
                if leaflet in self.leaflet_database.leaflets:
                    self.leaflet_database.leaflets.remove(leaflet)
                else:
                    self.leaflet_database.leaflets.append(leaflet)

    def process_queries(self):
        q = int(line := sys.stdin.readline())
        top_leaflet = -1

        for _ in range(q):
            l, r, pl, pr = [int(x) for x in line.split()]
            top_leaflet = self.leaflet_database.query(l, r)[0]

        return top_leaflet

def main():
    root = QueryEngine()
    root.read_queries(sys.stdin)
    sys.stdout.write(str(root.process_queries()))

sys.stdin = sys.__stdin__
main()
