import math

def distance_2d(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def shortest_path_polygon(polygon, s, t):
    n = len(polygon)

    # Find the starting point's previous and next vertices in the counter-clockwise order
    prev_s = polygon[(s - 1) % n]
    next_s = polygon[(s + 1) % n]

    # Compute the distance of moving directly from s to t
    direct_distance = distance_2d(polygon[s], polygon[t])

    # Define direction functions for transfers and descends
    def transfer(p1, p2):
        return distance_2d(p1, p2) < direct_distance

    def descend(x1, x2, y1, y2):
        return x1 == x2 and y1 >= y2

    def is_side(p1, p2):
        return abs(polygon[(p1 + 1) % n][0] - p2[0]) == abs(polygon[-1][0] - p1[0])

    # Case 1: direct move from s to t
    if transfer(prev_s, polygon[t]) and not descend(polygon[t][0], next_s[0], next_s[1], polygon[t][1]):
        return direct_distance

    # Case 2: transfer starting from s
    for i in range(n):
        if transfer(prev_s, polygon[i+1]) and not descend(polygon[t][0], next_s[0], next_s[1], polygon[i+1][1]):
            return transfer(prev_s, polygon[i+1]) + is_side(polygon[i+1], polygon[t]) * distance_2d(polygon[i+1], polygon[t])

    # Case 3: transfer starting from previous to current 
    for i in range(n):
        if transfer(prev_s, polygon[i+1]) and not descend(polygon[t][0], next_s[0], next_s[1], polygon[i+1][1]):
            return transfer(prev_s, polygon[i+1]) + is_side(polygon[i+1], polygon[t]) * is_side(polygon[i+1], next_s)

    return float('inf')

def validate_solution(polygon, s, t, expected):
    result = shortest_path_polygon(polygon, s, t)
    assert math.isclose(result, expected, rel_tol=1e-9), f"Expected {expected}, got {result}"
    print(f"✓ Expected {expected}, got {result}")

# Example validation
validate_solution([[1,1],[2,2],[3,3],[4,4]], 1, 4, 5.6502815398728847)
