def is_possible(palette, operations):
    color_set = set(palette)
    for operation in operations:
        new_palette = list(palette)  # Make a copy of the palette
        for index in operation[1]:
            if index in color_set:
                if index - 1 > 0:
                    if new_palette[index - 1] in color_set and color_set.index(new_palette[index - 1]) > color_set.index(new_palette[index]):
                        new_palette[index-1], new_palette[index] = new_palette[index], new_palette[index-1]
                if index + 1 < len(new_palette) and new_palette[index + 1] in color_set:
                    new_palette[index+1], new_palette[index] = new_palette[index], new_palette[index+1]
        palette = tuple(new_palette)
        if palette != color_set:
            return False
        color_set = set(palette)
        if "Y" in color_set and "B" in color_set and "R" not in color_set:
            return False
        if "B" in color_set and "R" in color_set and "Y" not in color_set:
            return False
    return True

