from collections import defaultdict, deque

def build_edges(n, tracks):
    graph = defaultdict(list)
    for start, end in tracks:
        graph[start-1].append(end-1)
    return graph

def dfs(current, visited, cycle, isOriginal):
    if current in cycle:
        return cycle[current]
    cycle[current] = ~(0b7 << 14)  # 1 bit for the original vertex
    for next_node in graph[current]:
        cycle[current] |= dfs(next_node, visited, cycle, isOriginal)
    cycle[current] |= isOriginal
    return cycle[current]

def find_safe_places(n, m, tracks):
    graph = build_edges(n, tracks)
    cycle = defaultdict(int)  # Stores nodes of cycle

    for node in range(n):
        if node not in cycle:
            cycle = [-1] * (n + 1)  # Initialize above
            dfs(node, set([node]), cycle, False)

    # Largest connected group with the highest cycle number
    largest_non_cycle = 0
    max_group = [(0, 0, cycle)]
    for node, cycle_value in cycle.items():
        if cycle_value == 0:
            continue
        group_size = 1
        node = node
        while cycle_value > max_group[-1][2]:
            max_group.append((node, group_size, max_group[-1][2]))
            group_size = 0
        max_group[-1][1] += 1
        if cycle_value > largest_non_cycle:
            largest_non_cycle = max_group[-1][2]

    number_spots = n - largest_non_cycle
    return int(number_spots * 7 / 4)

# Read input
T = int(input())
for _ in range(T):
    n, m = map(int, input().split())
    tracks = [list(map(int, input().split())) for _ in range(m)]
    print(find_safe_places(n, m, tracks))
