from functools import lru_cache

def count_ways(n):
    """
    Calculate the number of ways to delete some edges in a tree to make the maximum matching unique.
    """
    MOD = 998244353

    # Number of ways to choose k edges from n-1 edges
    binomial_coefficient = [1] * (n + 1)

    # Pre-calculate binomial coefficients up to n-1
    for i in range(1, n):
        binomial_coefficient[i] = (binomial_coefficient[i-1] * (n-i)) % MOD

    @lru_cache(maxsize=None)
    def find_ways(i, has_edge):
        if i == n:
            return 1
        ways = binomial_coefficient[i] % MOD
        if has_edge:
            ways = (ways - 1 + MOD) % MOD
        if i > 1 and i < n - 1:
            ways = (ways * 2) % MOD
        return ways % MOD

    # Try removing edges in ascending order of their labels
    for i in range(1, n-1):
        for has_edge in (False, True):
            res = 0
            for j in range(1, i + 2):
                if has_edge:
                    res += find_ways(j, has_edge) * find_ways(n - 1, False) % MOD
                else:
                    res += find_ways(j, has_edge)
                res %= MOD
            if res < 0:
                res += MOD

    return (res * 2 - 1) % MOD

# Example usage:
# print(count_ways(4))  # Output: 4
# print(count_ways(4))  # Output: 6
# print(count_ways(1))  # Output: 1
