from collections import defaultdict, Counter

def is_yalalovichik(s):
    """
    Check if a substring is a Yalalovichik string.
    """
    n = len(s)
    left = [0] * n
    right = [0] * n
    for i in range(1, n):
        left[i] = max(0, left[i-1] + (s[i] == s[i-1] and i > 0))
        right[-i-1] = max(0, right[-i] + (s[-i] == s[-i-1] and i > 0))
    return left == right

def count_yalalovichik_substrings(n, s):
    """
    Count the number of Yalalovichik substrings in the given string.
    """
    count = 0
    sf = Counter(s)
    for i, c in enumerate(s):
        if sf[c] > 1:
            sf[c] -= 2
    for i, c in enumerate(s):
        if c not in sf:
            count += 1
    return count

