def find_permutation(n, k):
    count = 0
    permutation = []
    i = 1
    while count < k:
        permutation.append(i)
        count += (i + 1)
        i += 1
    if count == k:
        return "YES\n" + " ".join(map(str, permutation))
    else:
        return "NO"

