from collections import defaultdict

def count_yalalovichik_substrings(n, s):
    ord_map = {}
    for char in s:
        if char in ord_map:
            ord_map[char].append(len(s) - 1 - ord_map[char][-1])
        else:
            ord_map[char] = [n - len(s)]
    count = defaultdict(int)
    for i in range(n - 1):
        count[s[i]] += i + 1
    for char, indices in ord_map.items():
        for i, index in enumerate(indices):
            if i > 0:
                count[s[index]] += count[s[index-1]]
            if i < len(indices) - 1:
                count[s[index]] += count[s[index+1]]
    return sum(count[char] for char in count)

